Here is an example of a complete React component for a shopping cart with state management using Redux Toolkit:

**Shopping Cart Component:**

```jsx
import React from'react';
import { useSelector, useDispatch } from'react-redux';
import { CartState, CartActions } from './store/reducers/cartReducer';
import { selectCart } from './store/selectors';
import './ShoppingCart.css';

const ShoppingCart = () => {
  const cart = useSelector(selectCart);
  const dispatch = useDispatch();

  const handleAddItem = (item) => {
    dispatch(CartActions.addItem(item));
  };

  const handleRemoveItem = (item) => {
    dispatch(CartActions.removeItem(item));
  };

  return (
    <div className="cart-container">
      <h2>Shopping Cart</h2>
      <ul>
        {cart.map((item) => (
          <li key={item.id}>
            <span>{item.name}</span>
            <span>${item.price}</span>
            <span>
              <button onClick={() => handleRemoveItem(item)}>Remove</button>
            </span>
          </li>
        ))}
      </ul>
      <button onClick={() => handleAddItem({ id: 1, name: 'Test Item', price: 10.99 })}>
        Add Item
      </button>
    </div>
  );
};

export default ShoppingCart;
```

**store/reducers/cartReducer.js:**

```javascript
import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  items: [],
};

const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addItem(state, action) {
      state.items = [...state.items, action.payload];
    },
    removeItem(state, action) {
      const index = state.items.findIndex((item) => item.id === action.payload.id);
      if (index >= 0) {
        state.items.splice(index, 1);
      }
    },
  },
});

export const { addItem, removeItem } = cartSlice.actions;
export default cartSlice.reducer;
```

