import { createSlice } from '@reduxjs/toolkit';
import cartJson from '../data/cart.json'; // mock cart data

const initialState = {
  items: cartJson.items,
  totalPrice: cartJson.totalPrice,
  tax: cartJson.tax,
  shipping: cartJson.shipping,
};

const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addItem(state, action) {
      const existingItem = state.items.find((item) => item.id === action.payload.id);
      if (existingItem) {
        existingItem.quantity += action.payload.quantity;
      } else {
        state.items.push({...action.payload, quantity: action.payload.quantity });
      }
      state.totalPrice += action.payload.price * action.payload.quantity;
    },
    removeItem(state, action) {
      const index = state.items.findIndex((item) => item.id === action.payload.id);
      if (index >= 0) {
        state.items.splice(index, 1);
        state.totalPrice -= state.items[index].price * state.items[index].quantity;
      }
    },
    updateQuantity(state, action) {
      const index = state.items.findIndex((item) => item.id === action.payload.id);
      if (index >= 0) {
        state.items[index].quantity = action.payload.quantity;
        state.totalPrice -= state.items[index].price * (state.items[index].quantity - action.payload.quantity);
      }
    },
    clearCart(state) {
      state.items = [];
      state.totalPrice = 0;
    },
  },
});

export const { addItem, removeItem, updateQuantity, clearCart } = cartSlice.actions;
export default cartSlice.reducer;
```
